import org.junit.jupiter.api.Test;

/** VALUES execution and physical recipes must not retain caller-owned mutable row storage. */
class LmdbValuesPlanOwnershipTest {

	@Test
	void callerSlotAndIdArraysCannotChangeScalarOrBatchResults() throws IOException {
		int[] slots = { 0, 1 };
		long[] ids = { 11L, 21L };
		SlotPlan plan = SlotPlan.values(new ValuesRow[] { new ValuesRow(slots, ids) });

		slots[0] = 2;
		ids[0] = 99L;

		List<List<Long>> expected = List.of(List.of(11L, 21L, UNKNOWN_ID));
		assertThat(scalarRows(plan)).as("scalar VALUES owns the original slots and ids").isEqualTo(expected);
		assertThat(batchRows(plan)).as("batch VALUES owns the original slots and ids").isEqualTo(expected);
	}

	@Test
	void callerRowsCannotChangeDuplicatesUndefOrAliases() throws IOException {
		ValuesRow duplicate = new ValuesRow(new int[] { 0, 1 }, new long[] { 11L, 11L });
		ValuesRow[] callerRows = {
				duplicate, duplicate, new ValuesRow(new int[0], new long[0]),
				new ValuesRow(new int[] { 1 }, new long[] { 21L })
		};
		ValuesPlan plan = (ValuesPlan) SlotPlan.values(callerRows, true);
		SlotPlan aliased = SlotPlan.extension(plan, new CopyBinding[] { CopyBinding.slot(2, 0) });

		callerRows[0] = new ValuesRow(new int[] { 0 }, new long[] { 99L });
		callerRows[2] = new ValuesRow(new int[] { 1 }, new long[] { 88L });

		assertThat(plan.producedMask()).isEqualTo(0b11L);
		assertThat(plan.bindsAllSlotsEveryRow).isFalse();
		assertThat(plan.exactFilterRewrite).isTrue();
		assertThat(scalarRows(aliased)).as("duplicates, UNDEF, row order and slot aliases survive")
				.containsExactly(List.of(11L, 11L, 11L), List.of(11L, 11L, 11L),
						List.of(UNKNOWN_ID, UNKNOWN_ID, UNKNOWN_ID), List.of(UNKNOWN_ID, 21L, UNKNOWN_ID));
		assertThat(batchRows(plan)).as("batch VALUES retains the same input rows")
				.containsExactly(List.of(11L, 11L, UNKNOWN_ID), List.of(11L, 11L, UNKNOWN_ID),
						List.of(UNKNOWN_ID, UNKNOWN_ID, UNKNOWN_ID), List.of(UNKNOWN_ID, 21L, UNKNOWN_ID));
	}

	@Test
	void preparedRecipeStillMatchesAfterCallerMutatesTheInputArrays() {
		int[] slots = { 0 };
		long[] ids = { 11L };
		ValuesRow[] callerRows = { new ValuesRow(slots, ids) };
		SlotPlan values = SlotPlan.values(callerRows);
		SlotPlan aliased = SlotPlan.extension(values, new CopyBinding[] { CopyBinding.slot(2, 0) });
		NativePhysicalInputRecipe recipe = NativePhysicalInputRecipe.capture(aliased);
		assertThat(recipe).isNotNull();
		assertThat(recipe.matches(aliased)).isTrue();

		slots[0] = 1;
		ids[0] = 99L;
		callerRows[0] = new ValuesRow(new int[] { 2 }, new long[] { 77L });

		assertThat(recipe.matches(aliased)).as("the prepared input still describes the same executable table")
				.isTrue();
	}

	@Test
	void independentlyOwnedRuntimeTablesCannotMatchOnlyBecauseIdsCoincide() {
		LmdbNativeRowDetachmentTest.FakeStoreSource store = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		NativeExecutionContext firstContext = new NativeExecutionContext();
		NativeExecutionContext secondContext = new NativeExecutionContext();
		try {
			LmdbNativeTermAuthority firstAuthority = new LmdbNativeTermAuthority(store, PlanValueCatalog.EMPTY,
					firstContext);
			LmdbNativeTermAuthority secondAuthority = new LmdbNativeTermAuthority(store, PlanValueCatalog.EMPTY,
					secondContext);
			long firstId = firstAuthority.idOfOrIntern(SimpleValueFactory.getInstance().createLiteral("first"));
			long secondId = secondAuthority.idOfOrIntern(SimpleValueFactory.getInstance().createLiteral("second"));
			assertThat(firstAuthority.kind(firstId)).isEqualTo(NativeIdKind.RUNTIME);
			assertThat(secondAuthority.kind(secondId)).isEqualTo(NativeIdKind.RUNTIME);
			assertThat(firstId).as("independent runtime authorities reuse the same raw id").isEqualTo(secondId);
			assertThat(firstAuthority.valueOf(firstId)).isNotEqualTo(secondAuthority.valueOf(secondId));

			ValuesPlan first = new ValuesPlan(
					new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { firstId }) });
			ValuesPlan second = new ValuesPlan(
					new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { secondId }) });
			NativePhysicalInputRecipe recipe = NativePhysicalInputRecipe.capture(first);
			assertThat(recipe == null || !recipe.matches(second))
					.as("execution-owned runtime tables cannot share a receipt based on equal raw ids")
					.isTrue();
		} finally {
			firstContext.close();
			secondContext.close();
		}
	}

	@Test
	void compiledReceiptFollowsItsTableThroughWorkerRebinding() throws IOException {
		int domains = ValuesPlan.ID_DOMAIN_STORE | ValuesPlan.ID_DOMAIN_OWN_PLAN;
		ValuesRow[] rows = {
				new ValuesRow(new int[] { 0 }, new long[] { 11L }),
				new ValuesRow(new int[] { 0 }, new long[] { 21L })
		};
		ValuesPlan values = (ValuesPlan) SlotPlan.values(rows, false, domains);
		SlotPlan input = SlotPlan.extension(values, new CopyBinding[] { CopyBinding.slot(2, 0) });
		NativePhysicalInputRecipe recipe = NativePhysicalInputRecipe.capture(input);
		assertThat(recipe).isNotNull();
		assertThat(recipe.valuesIdDomains()).isEqualTo(domains);

		try (NativeWorkerPlanBinder binder = new NativeWorkerPlanBinder(null)) {
			SlotPlan worker = binder.bind(input);
			assertThat(worker).isNotSameAs(input).isInstanceOf(ExtensionPlan.class);
			assertThat(((ExtensionPlan) worker).arg).isSameAs(values);
			assertThat(recipe.matches(worker)).isTrue();
		}

		SlotPlan independent = SlotPlan.extension(SlotPlan.values(rows, false, domains),
				new CopyBinding[] { CopyBinding.slot(2, 0) });
		assertThat(recipe.matches(independent)).as("equal rows are not a shared table identity").isFalse();
	}

	@Test
	void accumulatedRuntimeTableOwnsItsInputAndHasNoCompiledReceipt() throws IOException {
		int[] slots = { 0, 1 };
		List<Long> tuple = new ArrayList<>(List.of(11L, 21L));
		List<List<Long>> tuples = new ArrayList<>();
		tuples.add(tuple);
		ValuesPlan values = ValuesPlan.runtimeFixedSlots(slots, tuples);

		slots[0] = 2;
		tuple.set(0, 99L);
		tuples.clear();

		assertThat(values.compiledReceipt()).isNull();
		assertThat(NativePhysicalInputRecipe.capture(values)).isNull();
		assertThat(scalarRows(values)).containsExactly(List.of(11L, 21L, UNKNOWN_ID));
		assertThat(batchRows(values)).containsExactly(List.of(11L, 21L, UNKNOWN_ID));
	}

	private static List<List<Long>> scalarRows(SlotPlan plan) throws IOException {
		RowState row = row();
		List<List<Long>> result = new ArrayList<>();
		try (RowCursor cursor = plan.open(row)) {
			while (cursor.next()) {
				result.add(List.of(row.slots[0], row.slots[1], row.slots[2]));
			}
		}
		return result;
	}

	private static List<List<Long>> batchRows(SlotPlan plan) throws IOException {
		RowState row = row();
		List<List<Long>> result = new ArrayList<>();
		try (BatchCursor cursor = plan.openBatch(row, 2)) {
			NativeBatch batch = new NativeBatch(3, 2);
			int count;
			while ((count = cursor.fill(batch)) > 0) {
				for (int index = 0; index < count; index++) {
					result.add(List.of(batch.get(0, index), batch.get(1, index), batch.get(2, index)));
				}
			}
		}
		return result;
	}

	private static RowState row() {
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		names.put("first", 0);
		names.put("second", 1);
		names.put("alias", 2);
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(new ArrayList<>(names.keySet()));
		RowState row = new RowState(null, layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, UNKNOWN_ID);
		row.recomputeBoundMask();
		row.encounterOrderRequired = true;
		return row;
	}
}
